import http.client, json, os, threading, time, uuid
import boto3
BOOT = uuid.uuid4().hex
MODE = os.environ['PROBE_MODE']
API = os.environ['AWS_LAMBDA_RUNTIME_API']
SQS = boto3.client('sqs')
LOCK = threading.Lock()
SEQ = 0
def emit(kind, **fields):
    global SEQ
    with LOCK:
        SEQ += 1
        record = {'kind': kind, 'boot': BOOT, 'mode': MODE, 'sequence': SEQ, 'pid': os.getpid(), 'unix_ns': time.time_ns(), 'monotonic_ns': time.monotonic_ns(), **fields}
        print('PROBE ' + json.dumps(record), flush=True)
        SQS.send_message(QueueUrl=os.environ['PROBE_QUEUE'], MessageBody=json.dumps(record))
def request(method, path, body=None, headers=None):
    conn = http.client.HTTPConnection(API, timeout=10)
    conn.request(method, path, None if body is None else json.dumps(body), headers or {})
    response = conn.getresponse()
    raw = response.read().decode()
    captured = {'status': response.status, 'headers': dict(response.getheaders()), 'body': raw, 'received_unix_ns': time.time_ns()}
    conn.close()
    return captured
def registered(name):
    response = request('POST', '/2020-01-01/extension/register', {'events': ['INVOKE', 'SHUTDOWN']}, {'Lambda-Extension-Name': name})
    emit('register', response=response)
    return next((value for key, value in response['headers'].items() if key.lower() == 'lambda-extension-identifier'), None)
ERROR = {'errorMessage': 'Owned deliberate extension failure', 'errorType': 'Probe.ExtensionFailure', 'stackTrace': []}
def error_call(identifier, phase, label):
    response = request('POST', '/2020-01-01/extension/' + phase + '/error', ERROR, {'Lambda-Extension-Identifier': identifier, 'Lambda-Extension-Function-Error-Type': 'Probe.Deliberate'})
    emit(label, response=response)
def loop(identifier, internal=False):
    headers = {'Lambda-Extension-Identifier': identifier}
    while True:
        response = request('GET', '/2020-01-01/extension/event/next', headers=headers)
        emit('next', response=response, internal=internal)
        if response['status'] != 200:
            return
        event = json.loads(response['body'])
        if event['eventType'] == 'SHUTDOWN':
            emit('shutdown', event=event, internal=internal, deadline_remaining_ms=event['deadlineMs'] - time.time_ns()/1000000)
            if MODE == 'exit_error_shutdown':
                error_call(identifier, 'exit', 'exit_error_shutdown_response')
                error_call(identifier, 'exit', 'exit_error_shutdown_repeat')
                emit('next_after_exit_error', response=request('GET', '/2020-01-01/extension/event/next', headers=headers))
            return
        if MODE in ('invoke_exit', 'post_response_exit', 'invoke_exit_error'):
            marker = '/tmp/failure-' + MODE
            if not os.path.exists(marker):
                with open(marker, 'w') as f: f.write(BOOT)
                time.sleep(0.25 if MODE == 'invoke_exit' else 0.8)
                if MODE == 'invoke_exit_error':
                    error_call(identifier, 'exit', 'exit_error_during_invoke_response')
                    error_call(identifier, 'exit', 'exit_error_during_invoke_repeat')
                emit('process_exit', exit_code=17)
                os._exit(17)
        if MODE == 'init_error_during_invoke':
            marker = '/tmp/failure-' + MODE
            if not os.path.exists(marker):
                with open(marker, 'w') as f: f.write(BOOT)
                error_call(identifier, 'init', 'init_error_during_invoke_response')
                emit('next_after_init_error_during_invoke', response=request('GET', '/2020-01-01/extension/event/next', headers=headers))
                return
